    fun saveBiz(){prefs.edit().putBoolean("biz_enabled",enabled).putString("biz_name",bizName).putString("biz_category",category).putString("biz_description",description).putString("biz_address",address).putString("biz_hours",hours).putString("biz_email",email).putString("biz_website",website).putString("biz_social",social).putString("biz_brochure",brochure).putString("biz_cta",cta).putBoolean("biz_open",openNow).apply()}
