    fun shareProfile(){val text=buildString{append(if(enabled&&bizName.isNotBlank())bizName else name);if(enabled&&category.isNotBlank()){append("\n");append(category)};if(enabled&&description.isNotBlank()){append("\n");append(description)}else if(about.isNotBlank()){append("\n");append(about)};if(vm.profile.phone.isNotBlank()){append("\nPhone: ");append(vm.profile.phone)};if(enabled&&address.isNotBlank()){append("\nAddress: ");append(address)};if(enabled&&hours.isNotBlank()){append("\nHours: ");append(hours)};if(enabled&&website.isNotBlank()){append("\nWebsite: ");append(website)}};runCatching{val i=android.content.Intent(android.content.Intent.ACTION_SEND).apply{type="text/plain";putExtra(android.content.Intent.EXTRA_TEXT,text)};context.startActivity(android.content.Intent.createChooser(i,"Share profile"))}}
    sharing?.let{item->AlertDialog(onDismissRequest={sharing=null},title={Text("Send catalogue item")},text={LazyColumn(Modifier.heightIn(max=360.dp)){item{Text("Choose a conversation",style=MaterialTheme.typography.bodySmall)};items(vm.chats.filterNot{it.archived}.take(30),key={it.id}){chat->ListItem(modifier=Modifier.clickable{val msg=buildString{append(item.type);append(": ");append(item.title);if(bizName.isNotBlank()){append("\n");append(bizName)};if(item.offer.isNotBlank()){append("\nOffer: ");append(item.offer)}else if(item.price.isNotBlank()){append("\nPrice: ");append(item.price)};if(item.description.isNotBlank()){append("\n");append(item.description)};append("\nAvailability: ");append(if(item.available)"Available" else "Unavailable");if(cta.isNotBlank()){append("\n\n");append(cta)}};vm.sendMessage(chat.id,msg);sharing=null;vm.lastToast="Catalogue item sent"},leadingContent={Avatar(chat.title,40.dp)},headlineContent={Text(chat.title,maxLines=1,overflow=TextOverflow.Ellipsis)},trailingContent={Icon(Icons.Outlined.Send,null)})}}},confirmButton={TextButton(onClick={sharing=null}){Text("Close")}})}
    editing?.let{item->BusinessCatalogueEditor(item,onDismiss={editing=null}){saved->catalogue=(catalogue.filterNot{it.id==saved.id}+saved).sortedWith(compareByDescending<BusinessCatalogueItem>{it.featured}.thenBy{it.title.lowercase()});saveCatalogue();editing=null}}
    addMode?.let{mode->BusinessTextDialog(if(mode=="reply")"Add quick reply" else if(mode=="label")"Add business label" else "Add testimonial",onDismiss={addMode=null}){v->if(mode=="reply")replies=(replies+v).distinct().take(20) else if(mode=="label")labels=(labels+v).distinct().take(20) else testimonials=(testimonials+v).takeLast(10);saveTools();addMode=null}}
    Scaffold(topBar={TopAppBar(title={Text("Profile",fontWeight=FontWeight.SemiBold)},navigationIcon={IconButton(onClick={vm.back()}){Icon(Icons.Filled.ArrowBack,"Back")}},actions={IconButton(onClick={shareProfile()}){Icon(Icons.Outlined.Share,"Share profile")}})}){padding->
        Column(Modifier.fillMaxSize().padding(padding)){TabRow(selectedTabIndex=tab){listOf("Personal","Business","Catalogue","Tools").forEachIndexed{i,t->Tab(selected=tab==i,onClick={tab=i},text={Text(t,maxLines=1)})}}
            when(tab){
                0->LazyColumn(Modifier.fillMaxSize(),contentPadding=PaddingValues(bottom=28.dp)){item{Column(Modifier.fillMaxWidth().padding(20.dp),horizontalAlignment=Alignment.CenterHorizontally){Avatar(name.ifBlank{"You"},104.dp);Spacer(Modifier.height(10.dp));Text(vm.profile.phone,color=MaterialTheme.colorScheme.onSurfaceVariant)}};item{SectionLabel("Personal profile")};item{Column(Modifier.padding(horizontal=16.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){OutlinedTextField(name,{name=it},Modifier.fillMaxWidth(),label={Text("Name")},singleLine=true);OutlinedTextField(about,{about=it},Modifier.fillMaxWidth(),label={Text("About")},maxLines=3);OutlinedTextField(vm.profile.phone,{},Modifier.fillMaxWidth(),label={Text("Phone")},enabled=false,singleLine=true);Button(onClick={vm.saveProfile(name.trim(),about.trim())},modifier=Modifier.fillMaxWidth().height(50.dp),enabled=name.isNotBlank()){Text("Save personal profile")}}};item{SectionLabel("Profile actions")};item{SettingsRow(Icons.Outlined.Share,"Share profile","Share personal or business details"){shareProfile()}};item{SettingsRow(Icons.Outlined.Lock,"Privacy controls","Last seen, read receipts and caller controls"){vm.navigate(AppScreen.Privacy)}}}
                1->LazyColumn(Modifier.fillMaxSize(),contentPadding=PaddingValues(bottom=28.dp)){item{Card(Modifier.fillMaxWidth().padding(16.dp),shape=RoundedCornerShape(22.dp)){Column(Modifier.padding(20.dp),horizontalAlignment=Alignment.CenterHorizontally){Avatar(bizName.ifBlank{name}.ifBlank{"B"},82.dp);Spacer(Modifier.height(8.dp));Text(bizName.ifBlank{"Set up your business"},style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold);if(category.isNotBlank())Text(category,color=MaterialTheme.colorScheme.onSurfaceVariant);Spacer(Modifier.height(8.dp));Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){AssistChip(onClick={},label={Text(if(openNow)"Open now" else "Closed")});AssistChip(onClick={},label={Text(catalogue.size.toString()+" items")})}}}};item{SectionLabel("Business identity")};item{Column(Modifier.padding(horizontal=16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){ToggleRow("Business profile","Enable professional profile and catalogue",enabled){enabled=it;saveBiz()};OutlinedTextField(bizName,{bizName=it;saveBiz()},Modifier.fillMaxWidth(),label={Text("Business name")},singleLine=true);OutlinedTextField(category,{category=it;saveBiz()},Modifier.fillMaxWidth(),label={Text("Category")},singleLine=true);OutlinedTextField(description,{description=it;saveBiz()},Modifier.fillMaxWidth(),label={Text("Description")},minLines=2,maxLines=4);OutlinedTextField(address,{address=it;saveBiz()},Modifier.fillMaxWidth(),label={Text("Address")},minLines=2);OutlinedTextField(hours,{hours=it;saveBiz()},Modifier.fillMaxWidth(),label={Text("Business hours")},singleLine=true);ToggleRow("Open now","Manual availability indicator",openNow){openNow=it;saveBiz()}}};item{SectionLabel("Contact & links")};item{Column(Modifier.padding(horizontal=16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){OutlinedTextField(email,{email=it;saveBiz()},Modifier.fillMaxWidth(),label={Text("Business email")},singleLine=true);OutlinedTextField(website,{website=it;saveBiz()},Modifier.fillMaxWidth(),label={Text("Website")},singleLine=true);OutlinedTextField(social,{social=it;saveBiz()},Modifier.fillMaxWidth(),label={Text("Social link")},singleLine=true);OutlinedTextField(brochure,{brochure=it;saveBiz()},Modifier.fillMaxWidth(),label={Text("Brochure / document link")},singleLine=true);OutlinedTextField(cta,{cta=it;saveBiz()},Modifier.fillMaxWidth(),label={Text("Customer CTA")},singleLine=true);Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){OutlinedButton(onClick={shareProfile()},modifier=Modifier.weight(1f)){Text("Share")};OutlinedButton(onClick={runCatching{val raw=website.trim();if(raw.isNotBlank()){val u=if(raw.startsWith("http"))raw else "https://"+raw;context.startActivity(android.content.Intent(android.content.Intent.ACTION_VIEW,android.net.Uri.parse(u)))}}},modifier=Modifier.weight(1f),enabled=website.isNotBlank()){Text("Website")};OutlinedButton(onClick={runCatching{context.startActivity(android.content.Intent(android.content.Intent.ACTION_VIEW,android.net.Uri.parse("geo:0,0?q="+android.net.Uri.encode(address))))}},modifier=Modifier.weight(1f),enabled=address.isNotBlank()){Text("Directions")}}}}}
                2->BusinessCatalogueTab(catalogue,bizName,onAdd={editing=BusinessCatalogueItem(System.currentTimeMillis().toString())},onEdit={editing=it},onDelete={target->catalogue=catalogue.filterNot{it.id==target.id};saveCatalogue()},onShare={sharing=it})
                else->LazyColumn(Modifier.fillMaxSize(),contentPadding=PaddingValues(bottom=28.dp)){val score=listOf(bizName,category,description,address,hours,email,website).count{it.isNotBlank()}+if(catalogue.isNotEmpty())1 else 0;val complete=(score/8f).coerceIn(0f,1f);item{Card(Modifier.fillMaxWidth().padding(16.dp)){Column(Modifier.padding(18.dp)){Text("Business profile completeness",fontWeight=FontWeight.Bold);Spacer(Modifier.height(8.dp));LinearProgressIndicator(progress=complete,modifier=Modifier.fillMaxWidth());Spacer(Modifier.height(5.dp));Text((complete*100).toInt().toString()+"% complete",style=MaterialTheme.typography.bodySmall)}}};item{SectionLabel("Customer messaging templates")};item{Column(Modifier.padding(horizontal=16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){ToggleRow("Greeting message","Reusable welcome template",greetingEnabled){greetingEnabled=it;saveTools()};if(greetingEnabled)OutlinedTextField(greeting,{greeting=it;saveTools()},Modifier.fillMaxWidth(),label={Text("Greeting")},minLines=2);ToggleRow("Away message","Reusable after-hours template",awayEnabled){awayEnabled=it;saveTools()};if(awayEnabled)OutlinedTextField(away,{away=it;saveTools()},Modifier.fillMaxWidth(),label={Text("Away message")},minLines=2);Text("Templates are stored locally. Automatic server sending is intentionally not enabled in this UI-only batch.",style=MaterialTheme.typography.bodySmall,color=MaterialTheme.colorScheme.onSurfaceVariant)}};item{SectionLabel("Quick replies")};items(replies){v->ListItem(headlineContent={Text(v)},leadingContent={Icon(Icons.Outlined.Chat,null)},trailingContent={IconButton(onClick={replies=replies-v;saveTools()}){Icon(Icons.Outlined.Delete,"Remove")}})};item{OutlinedButton(onClick={addMode="reply"},modifier=Modifier.fillMaxWidth().padding(horizontal=16.dp)){Text("Add quick reply")}};item{SectionLabel("Business labels")};items(labels){v->ListItem(headlineContent={Text(v)},leadingContent={Icon(Icons.Outlined.Label,null)},trailingContent={IconButton(onClick={labels=labels-v;saveTools()}){Icon(Icons.Outlined.Close,"Remove")}})};item{OutlinedButton(onClick={addMode="label"},modifier=Modifier.fillMaxWidth().padding(horizontal=16.dp)){Text("Add label")}};item{SectionLabel("Testimonials")};items(testimonials){v->ListItem(headlineContent={Text(v,maxLines=3,overflow=TextOverflow.Ellipsis)},leadingContent={Icon(Icons.Outlined.StarOutline,null)},trailingContent={IconButton(onClick={testimonials=testimonials-v;saveTools()}){Icon(Icons.Outlined.Close,"Remove")}})};item{OutlinedButton(onClick={addMode="testimonial"},modifier=Modifier.fillMaxWidth().padding(horizontal=16.dp)){Text("Add testimonial")}}}
            }
        }
    }
}
private data class BusinessCatalogueItem(val id:String,val type:String="Product",val title:String="",val category:String="",val price:String="",val offer:String="",val description:String="",val available:Boolean=true,val featured:Boolean=false)
@Composable
private fun BusinessCatalogueTab(values:List<BusinessCatalogueItem>,businessName:String,onAdd:()->Unit,onEdit:(BusinessCatalogueItem)->Unit,onDelete:(BusinessCatalogueItem)->Unit,onShare:(BusinessCatalogueItem)->Unit){var q by remember{mutableStateOf("")};var filter by remember{mutableStateOf("All")};val categories=listOf("All")+values.map{it.category.ifBlank{"Other"}}.distinct().sorted();val visible=values.filter{(q.isBlank()||it.title.contains(q,true)||it.description.contains(q,true))&&(filter=="All"||it.category.ifBlank{"Other"}==filter)};LazyColumn(Modifier.fillMaxSize(),contentPadding=PaddingValues(bottom=28.dp)){item{Column(Modifier.padding(16.dp)){Text("Business catalogue",style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold);Text(businessName.ifBlank{"Products and services"},color=MaterialTheme.colorScheme.onSurfaceVariant);Spacer(Modifier.height(10.dp));OutlinedTextField(q,{q=it},Modifier.fillMaxWidth(),leadingIcon={Icon(Icons.Outlined.Search,null)},placeholder={Text("Search catalogue")},singleLine=true);Spacer(Modifier.height(8.dp));LazyRow(horizontalArrangement=Arrangement.spacedBy(8.dp)){items(categories){c->FilterChip(selected=filter==c,onClick={filter=c},label={Text(c)})}};Spacer(Modifier.height(10.dp));Button(onClick=onAdd,modifier=Modifier.fillMaxWidth()){Text("Add product or service")}}};if(visible.isEmpty())item{EmptyState(Icons.Outlined.ShoppingBag,"Catalogue is empty","Add products or services with price, description and availability.")};items(visible,key={it.id}){v->Card(Modifier.fillMaxWidth().padding(horizontal=14.dp,vertical=6.dp),shape=RoundedCornerShape(20.dp)){Column(Modifier.padding(16.dp)){Row{Column(Modifier.weight(1f)){Text(v.title,fontWeight=FontWeight.Bold,style=MaterialTheme.typography.titleMedium);Text(listOf(v.type,v.category).filter{it.isNotBlank()}.joinToString(" / "),style=MaterialTheme.typography.bodySmall,color=MaterialTheme.colorScheme.onSurfaceVariant);if(v.offer.isNotBlank())Text(v.offer,fontWeight=FontWeight.Bold,color=MaterialTheme.colorScheme.primary)else if(v.price.isNotBlank())Text(v.price,fontWeight=FontWeight.Bold,color=MaterialTheme.colorScheme.primary)};if(v.featured)AssistChip(onClick={},label={Text("Featured")})};if(v.description.isNotBlank()){Spacer(Modifier.height(8.dp));Text(v.description,maxLines=3,overflow=TextOverflow.Ellipsis)};Spacer(Modifier.height(8.dp));Row(verticalAlignment=Alignment.CenterVertically){AssistChip(onClick={},label={Text(if(v.available)"Available" else "Unavailable")});Spacer(Modifier.weight(1f));IconButton(onClick={onEdit(v)}){Icon(Icons.Outlined.Edit,"Edit")};IconButton(onClick={onDelete(v)}){Icon(Icons.Outlined.Delete,"Delete",tint=MaterialTheme.colorScheme.error)};FilledTonalButton(onClick={onShare(v)}){Text("Send")}}}}}}}
@Composable
private fun BusinessCatalogueEditor(value:BusinessCatalogueItem,onDismiss:()->Unit,onSave:(BusinessCatalogueItem)->Unit){var v by remember(value.id){mutableStateOf(value)};AlertDialog(onDismissRequest=onDismiss,title={Text(if(value.title.isBlank())"Add catalogue item" else "Edit catalogue item")},text={LazyColumn(Modifier.heightIn(max=500.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){item{Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){FilterChip(selected=v.type=="Product",onClick={v=v.copy(type="Product")},label={Text("Product")});FilterChip(selected=v.type=="Service",onClick={v=v.copy(type="Service")},label={Text("Service")})}};item{OutlinedTextField(v.title,{v=v.copy(title=it)},Modifier.fillMaxWidth(),label={Text("Title")})};item{OutlinedTextField(v.category,{v=v.copy(category=it)},Modifier.fillMaxWidth(),label={Text("Category")})};item{OutlinedTextField(v.price,{v=v.copy(price=it)},Modifier.fillMaxWidth(),label={Text("Price")})};item{OutlinedTextField(v.offer,{v=v.copy(offer=it)},Modifier.fillMaxWidth(),label={Text("Offer price")})};item{OutlinedTextField(v.description,{v=v.copy(description=it)},Modifier.fillMaxWidth(),label={Text("Description")},minLines=3)};item{ToggleRow("Available","Customers can enquire about this item",v.available){v=v.copy(available=it)}};item{ToggleRow("Featured","Show this item first",v.featured){v=v.copy(featured=it)}}}},confirmButton={Button(onClick={onSave(v.copy(title=v.title.trim(),category=v.category.trim()))},enabled=v.title.isNotBlank()){Text("Save")}},dismissButton={TextButton(onClick=onDismiss){Text("Cancel")}})}
@Composable
private fun BusinessTextDialog(title:String,onDismiss:()->Unit,onSave:(String)->Unit){var text by remember{mutableStateOf("")};AlertDialog(onDismissRequest=onDismiss,title={Text(title)},text={OutlinedTextField(text,{text=it},Modifier.fillMaxWidth(),label={Text("Text")},minLines=2)},confirmButton={Button(onClick={onSave(text.trim())},enabled=text.isNotBlank()){Text("Add")}},dismissButton={TextButton(onClick=onDismiss){Text("Cancel")}})}
private fun readBusinessList(raw:String?,fallback:List<String>):List<String> = runCatching{val a=org.json.JSONArray(raw?:return@runCatching fallback);List(a.length()){a.optString(it)}.filter{it.isNotBlank()}}.getOrDefault(fallback)
private fun writeBusinessList(values:List<String>):String = org.json.JSONArray().apply{values.forEach{put(it)}}.toString()
private fun readBusinessCatalogue(raw:String):List<BusinessCatalogueItem> = runCatching{val a=org.json.JSONArray(raw);buildList{for(i in 0 until a.length()){val o=a.getJSONObject(i);add(BusinessCatalogueItem(o.optString("id",i.toString()),o.optString("type","Product"),o.optString("title"),o.optString("category"),o.optString("price"),o.optString("offer"),o.optString("description"),o.optBoolean("available",true),o.optBoolean("featured",false)))}}}.getOrDefault(emptyList())
private fun writeBusinessCatalogue(values:List<BusinessCatalogueItem>):String = org.json.JSONArray().apply{values.forEach{v->put(org.json.JSONObject().apply{put("id",v.id);put("type",v.type);put("title",v.title);put("category",v.category);put("price",v.price);put("offer",v.offer);put("description",v.description);put("available",v.available);put("featured",v.featured)})}}.toString()
